/** Учебные входы и рабочие функции, без мира, шагов моделирования или RNG. */
export function guideFeelingExample(){
 const body={energy:25,health:50,stomach:0,pain:0};
 const feeling=energy=>controllerFeeling({temporal:true,traits:{values:[energy,0,0,0]}},body,RULES.stomachCapacity);
 return {body,positive:feeling(1),negative:feeling(-1),indifferent:feeling(0)};
}
export function guideOperationExample(){
 const options=Array.from({length:6},(_,i)=>({id:'move-'+i,score:0,operation:0}));
 options.push({id:'eat',score:0,operation:2});
 structuralEngine.operationProbabilities(options);
 return options;
}
export function guideMemoryExample(){
 const brain=createBrain([]);brain.temporal=true;
 const position={q:0,r:0},cell={...position,terrain:'land',food:2,isFoodSource:true};
 observe(brain,[cell],position,0,true,DT);
 const record=getMemory(brain,positionKey(position));
 const before=memoryBelief(record,0,brain.traits);cell.food=0;
 const later=memoryBelief(record,brain.traits.memoryAge,brain.traits);
 return {recorded:record.food,hiddenFood:cell.food,before,later};
}
const feeling=guideFeelingExample(),choices=guideOperationExample(),memory=guideMemoryExample();
